using System.Text.Json.Nodes;
using PowerShapeMcp;
using Xunit;

namespace PowerShapeMcp.Tests;
public sealed class OwnedOpenAdoptionTests
{
    static Fixture Config(bool enabled=true){var f=new Fixture();foreach(string flag in new[]{"workingCopyOpenExperimental","workingCopiesExperimental","entitySetsExperimental","documentBindingsExperimental","levelReadingExperimental","recoveryInspectionExperimental"})f.Config[flag]=true;f.Config["ownedOpenAdoptionExperimental"]=enabled;f.SaveConfig();return f;}
    [Theory][InlineData(false,true,true)][InlineData(true,true,false)][InlineData(false,false,false)]
    public void FullOnlySeparateFlag(bool readOnly,bool enabled,bool expected){var f=Config(enabled);using var session=new BridgeSession(f.Options(readOnly));var names=ToolCatalog.Create(session).Select(t=>t.ProtocolTool.Name).ToArray();foreach(string name in new[]{"adopt_owned_open_document","restore_owned_open_adoption"})Assert.Equal(expected,names.Contains(name));if(readOnly)Assert.Equal(8,names.Length);}
    [Theory][InlineData("\"true\"")][InlineData("1")][InlineData("null")]
    public void RejectNonBooleanConfig(string value){var f=Config();f.Config["ownedOpenAdoptionExperimental"]=JsonNode.Parse(value);f.SaveConfig();Assert.Throws<InvalidDataException>(()=>f.Options().ReadConfiguration());}
    [Fact]public void MissingOpenDependencyRefuses(){var f=Config();f.Config["workingCopyOpenExperimental"]=false;f.SaveConfig();Assert.Throws<InvalidDataException>(()=>f.Options().ReadConfiguration());}
    [Fact]public async Task UnknownHandlesStopBeforeIpc(){var f=Config();using var session=new BridgeSession(f.Options());var result=await new OwnedOpenAdoptionTools(session).Adopt(new string('a',32),new string('b',64),new string('c',64),new string('d',32),new string('e',32),CancellationToken.None);Assert.True(result.IsError);Assert.False(Directory.Exists(Path.Combine(f.Root,"requests")));}
    [Fact]public async Task CancellationBeforeSubmissionDoesNotIssueRequest(){var f=Config();using var session=new BridgeSession(f.Options());using var ct=new CancellationTokenSource();ct.Cancel();var result=await new OwnedOpenAdoptionTools(session).Adopt(new string('a',32),new string('b',64),new string('c',64),new string('d',32),new string('e',32),ct.Token);Assert.True(result.IsError);Assert.False(Directory.Exists(Path.Combine(f.Root,"requests")));}
    [Fact]public void FakeObservationCannotIssueCopyLease(){var f=Config();var store=new WorkingCopyStore();var result=new JsonObject{["state"]="owned_open_document_observed_unqualified",["bridgeRequestId"]=Guid.NewGuid().ToString("N"),["adoptionId"]=Guid.NewGuid().ToString("N"),["qualificationScope"]=OwnedOpenAdoptionProof.Scope,["nativeProviderQualified"]=false};Assert.Throws<ReferenceRejected>(()=>store.IssueAdoptedOpen(f.Root,result,new()));}
    static (Fixture F,JsonObject Reply,JsonObject Args,string Opened) NativeReceipt()
    {
        var f=Config();var id=Guid.NewGuid().ToString("N");var opened=Guid.NewGuid().ToString("N");var copy=Guid.NewGuid().ToString("N");string owner=new string('a',64);var args=new JsonObject{["openRequestId"]=opened,["openReceiptSha256"]=ArtifactProof.Freeze(f.Root,"responses/"+opened+".json",new(){["state"]="timeout_outcome_unknown",["operation"]="--mcp-operation "+opened}),["inspectionRequestId"]=new string('b',32),["inspectionSha256"]=new string('c',64),["listingRequestId"]=new string('d',32),["listingSha256"]=new string('e',64),["modelId"]=10,["windowNumber"]=2,["expiresUtc"]=LeaseTime.Format(DateTimeOffset.UtcNow.AddSeconds(200))};
        args["openPlanSha256"]=ArtifactProof.Freeze(f.Root,"copyopenplans/"+opened+".json",new(){["operation"]="open_working_copy",["operationId"]=opened,["copyId"]=copy,["ownershipSha256"]=owner,["workingPath"]=Path.Combine(f.Root,"workingcopies",copy,"Working_"+copy+".psmodel")});
        var hashes=new JsonArray();string? previous=null;string[] states=["prepared","execution_claimed","command_started"];
        for(int i=0;i<3;i++){string sha=ArtifactProof.Freeze(f.Root,"operations/"+opened+"/"+i.ToString("D6")+".json",new(){["operationId"]=opened,["planSha256"]=args["openPlanSha256"]!.DeepClone(),["sequence"]=i,["previousSha256"]=previous,["state"]=states[i]});hashes.Add(sha);previous=sha;}
        string claim=ArtifactProof.Freeze(f.Root,"workingcopies/"+copy+"/open-once.json",new(){["operationId"]=opened});
        var proof=new JsonObject{["schemaVersion"]=1,["adoptionId"]=id,["state"]="owned_open_document_adopted_observed",["qualificationScope"]=OwnedOpenAdoptionProof.Scope,["parameters"]=args.DeepClone(),["copyId"]=copy,["ownershipSha256"]=owner,["workingPath"]=Path.Combine(f.Root,"workingcopies",copy,"Working_"+copy+".psmodel"),["originalJournalHashes"]=hashes,["originalClaimSha256"]=claim,["nativeProviderQualified"]=true,["checkpointVerified"]=true,["sameContextObservationReads"]=2,["expiresUtc"]=args["expiresUtc"]!.DeepClone(),["timestampUtc"]=LeaseTime.Format(DateTimeOffset.UtcNow)};
        foreach(string flag in new[]{"cadMutationAttempted","contextChangeAttempted","geometryMutationAttempted","cadSaveAttempted","retryAllowed","originalCommandReturned","originalJournalModified","historicalSavedBytesCertified","fullTopologyEquivalent"})proof[flag]=false;
        string proofSha=ArtifactProof.Freeze(f.Root,"openadoptions/"+id+".json",proof);var once=new JsonObject{["schemaVersion"]=1,["qualificationScope"]=OwnedOpenAdoptionProof.Scope,["adoptionId"]=id,["adoptionSha256"]=proofSha,["copyId"]=copy,["ownershipSha256"]=owner,["noCommandReplay"]=true};foreach(string k in new[]{"openRequestId","openReceiptSha256","openPlanSha256"})once[k]=args[k]!.DeepClone();ArtifactProof.Freeze(f.Root,"openadoptions/"+opened+".once.json",once);
        var reply=proof.DeepClone().AsObject();reply.Remove("schemaVersion");reply.Remove("parameters");reply["bridgeRequestId"]=id;reply["adoptionSha256"]=proofSha;reply["adoption"]=proof;ArtifactProof.Freeze(f.Root,"responses/"+id+".json",reply);return(f,reply,args,opened);
    }
    [Fact]public void QualifiedAdoptionIssuesOnlyCurrentCopyLease(){var f=NativeReceipt();var store=new WorkingCopyStore();var result=store.IssueAdoptedOpen(f.F.Root,f.Reply,f.Args);string handle=result["workingCopyHandle"]!.GetValue<string>();var parameters=store.InspectParameters(handle);Assert.Equal(2,parameters.Count);Assert.Equal(f.Reply["copyId"]!.GetValue<string>(),parameters["copyId"]!.GetValue<string>());Assert.Throws<ReferenceRejected>(()=>new WorkingCopyStore().InspectParameters(handle));Assert.False(f.Reply["originalCommandReturned"]!.GetValue<bool>());}
    [Theory][InlineData("journal")][InlineData("plan")][InlineData("report")][InlineData("claim")][InlineData("response")][InlineData("once")]
    public void ChangedChainCannotIssueLease(string kind){var f=NativeReceipt();string id=f.Reply["adoptionId"]!.GetValue<string>(),copy=f.Reply["copyId"]!.GetValue<string>();string path=kind switch{"journal"=>"operations/"+f.Opened+"/000002.json","plan"=>"copyopenplans/"+f.Opened+".json","report"=>"openadoptions/"+id+".json","claim"=>"workingcopies/"+copy+"/open-once.json","once"=>"openadoptions/"+f.Opened+".once.json",_=>"responses/"+id+".json"};File.AppendAllText(Path.Combine(f.F.Root,path)," ");if(kind=="once")File.WriteAllText(Path.Combine(f.F.Root,path),"{}");if(kind=="response"){var changed=f.Reply.DeepClone().AsObject();changed["originalCommandReturned"]=true;File.WriteAllText(Path.Combine(f.F.Root,path),changed.ToJsonString());}Assert.ThrowsAny<Exception>(()=>new WorkingCopyStore().IssueAdoptedOpen(f.F.Root,f.Reply,f.Args));}
    [Fact]public void AddedReturnEventCannotMasqueradeAsAdoption(){var f=NativeReceipt();ArtifactProof.Freeze(f.F.Root,"operations/"+f.Opened+"/000003.json",new(){["state"]="command_returned"});Assert.Throws<ReferenceRejected>(()=>new WorkingCopyStore().IssueAdoptedOpen(f.F.Root,f.Reply,f.Args));}
    [Fact]public void SchemaDistinguishesHashesFromHandles(){var schema=OwnedOpenAdoptionTools.Schema();foreach(string key in new[]{"openReceiptSha256","openPlanSha256"})Assert.Equal("^[0-9a-f]{64}$",schema["properties"]![key]!["pattern"]!.GetValue<string>());Assert.False(schema["additionalProperties"]!.GetValue<bool>());}
    [Fact]public void RestoreSchemaAndUnknownProofDoNotIssueRequest(){var f=Config();using var session=new BridgeSession(f.Options());var schema=OwnedOpenAdoptionTools.Schema(true);Assert.Equal("^[0-9a-f]{64}$",schema["properties"]!["adoptionReceiptSha256"]!["pattern"]!.GetValue<string>());Assert.ThrowsAny<Exception>(()=>OwnedOpenAdoptionProof.RestoreParameters(f.Root,new(){["adoptionRequestId"]=new string('a',32),["adoptionReceiptSha256"]=new string('b',64),["candidateDocumentHandle"]=new string('c',32),["activeDocumentHandle"]=new string('d',32)},session.Candidates,session.Documents));Assert.False(Directory.Exists(Path.Combine(f.Root,"requests")));}
    [Fact]public void RestoredLeaseLinksInitialAdoptionWithoutReplacingItsOnceRecord(){var f=NativeReceipt();string initial=f.Reply["adoptionId"]!.GetValue<string>(),id=Guid.NewGuid().ToString("N");var oncePath=Path.Combine(f.F.Root,"openadoptions",f.Opened+".once.json");var onceBefore=File.ReadAllBytes(oncePath);var args=f.Args.DeepClone().AsObject();args["initialAdoptionId"]=initial;args["initialAdoptionSha256"]=f.Reply["adoptionSha256"]!.DeepClone();var proof=f.Reply["adoption"]!.DeepClone().AsObject();proof["state"]="owned_open_adoption_refreshed_observed";proof["adoptionId"]=id;proof["parameters"]=args.DeepClone();string sha=ArtifactProof.Freeze(f.F.Root,"openadoptions/"+id+".json",proof);var reply=f.Reply.DeepClone().AsObject();reply["state"]=proof["state"]!.DeepClone();reply["adoptionId"]=id;reply["bridgeRequestId"]=id;reply["adoptionSha256"]=sha;reply["adoption"]=proof;ArtifactProof.Freeze(f.F.Root,"responses/"+id+".json",reply);Assert.NotNull(new WorkingCopyStore().IssueAdoptedOpen(f.F.Root,reply,args)["workingCopyHandle"]);Assert.Equal(onceBefore,File.ReadAllBytes(oncePath));}
}
